"use client";

import { useId } from "react";
import type { ReactNode } from "react";
import { cn } from "./utils";

export interface RadioOption {
  value: string;
  label: ReactNode;
  description?: string;
  disabled?: boolean;
}

export interface RadioGroupProps {
  /** Shared `name` for the native radios. Auto-generated if omitted. */
  name?: string;
  legend?: string;
  options: RadioOption[];
  /** Controlled selected value. */
  value?: string;
  /** Initial value for uncontrolled usage. */
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  className?: string;
  orientation?: "vertical" | "horizontal";
}

/**
 * Client Component — a set of native radio inputs sharing one `name`, so
 * grouping and keyboard behavior are entirely native. `onValueChange` is
 * the only piece of state management layered on top.
 */
export function RadioGroup({
  name,
  legend,
  options,
  value,
  defaultValue,
  onValueChange,
  className,
  orientation = "vertical",
}: RadioGroupProps) {
  const generatedName = useId();
  const groupName = name ?? generatedName;

  return (
    <fieldset className={cn("m-0 flex flex-col gap-[var(--space-2)] border-0 p-0", className)}>
      {legend ? (
        <legend className="mb-[var(--space-1)] text-[var(--text-label-size)] font-[var(--weight-medium)] text-[var(--text-strong)]">
          {legend}
        </legend>
      ) : null}
      <div
        role="radiogroup"
        aria-label={legend}
        className={cn(
          "flex gap-[var(--space-3)]",
          orientation === "vertical" ? "flex-col" : "flex-row flex-wrap"
        )}
      >
        {options.map((option) => {
          const optionId = `${groupName}-${option.value}`;
          return (
            <div key={option.value} className="flex items-start gap-[var(--space-3)]">
              <input
                id={optionId}
                type="radio"
                name={groupName}
                value={option.value}
                disabled={option.disabled}
                checked={value !== undefined ? value === option.value : undefined}
                defaultChecked={
                  value === undefined ? defaultValue === option.value : undefined
                }
                onChange={(event) => {
                  if (event.target.checked) onValueChange?.(option.value);
                }}
                className="mt-[3px] h-5 w-5 shrink-0 cursor-pointer accent-[var(--action-primary)] disabled:cursor-not-allowed disabled:opacity-50"
              />
              <div className="flex flex-col">
                <label
                  htmlFor={optionId}
                  className="cursor-pointer text-[var(--text-body-size)] text-[var(--text-strong)]"
                >
                  {option.label}
                </label>
                {option.description ? (
                  <p className="text-[var(--text-caption-size)] text-[var(--text-muted)]">
                    {option.description}
                  </p>
                ) : null}
              </div>
            </div>
          );
        })}
      </div>
    </fieldset>
  );
}
